-- Local authority mappings and logical workspace continuity; cloud sessions stay in OS custody.
CREATE TABLE IF NOT EXISTS dpro_local_principals(user_id TEXT NOT NULL REFERENCES users(id),origin TEXT NOT NULL,account_id TEXT NOT NULL,issuer TEXT NOT NULL,subject TEXT NOT NULL,security_epoch INTEGER NOT NULL,registry_version INTEGER NOT NULL,device_id TEXT NOT NULL,device_public_key TEXT NOT NULL,approved_family_id TEXT NOT NULL,approved_token_version INTEGER NOT NULL,approved_factor_version INTEGER NOT NULL,verified_at INTEGER NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(user_id,origin),UNIQUE(origin,account_id));
CREATE TABLE IF NOT EXISTS dpro_trusted_devices(user_id TEXT NOT NULL,account_id TEXT NOT NULL,device_id TEXT NOT NULL,public_key TEXT NOT NULL,pinned_at INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,account_id,device_id));
CREATE TABLE IF NOT EXISTS dpro_workspaces(user_id TEXT NOT NULL,account_id TEXT NOT NULL,workspace_id TEXT NOT NULL,label TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN ('independent','continuity')),source_device_id TEXT,source_workspace_id TEXT,project_binding TEXT,selection_json TEXT NOT NULL,state TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(user_id,account_id,workspace_id));
CREATE TABLE IF NOT EXISTS dpro_workspace_resources(user_id TEXT NOT NULL,account_id TEXT NOT NULL,workspace_id TEXT NOT NULL,category TEXT NOT NULL,local_id TEXT NOT NULL,logical_id TEXT NOT NULL,PRIMARY KEY(user_id,account_id,workspace_id,category,local_id));
CREATE TABLE IF NOT EXISTS dpro_import_requests(user_id TEXT NOT NULL,account_id TEXT NOT NULL,request_id TEXT NOT NULL,peer_id TEXT NOT NULL,workspace_id TEXT NOT NULL,selection_json TEXT NOT NULL,selection_hash TEXT NOT NULL,state TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(user_id,account_id,request_id));
